export function currentLanguage() {
  return document.documentElement.lang === "es" ? "es" : "en";
}

export function t(key, values = {}) {
  const language = currentLanguage();
  const message = messages[language][key] ?? messages.es[key] ?? key;
  return Object.entries(values).reduce((result, [name, value]) => result.replaceAll(`{${name}}`, String(value)), message);
}

export function tx(value) {
  if (currentLanguage() !== "en") return value;
  if (typeof value !== "string") return value;
  if (terms[value]) return terms[value];
  return value.replaceAll("Datos aportados", "Supplied data").replaceAll("verificación pendiente", "verification pending").replaceAll("Nectárico", "Nectarian").replaceAll("Eratosteniano", "Eratosthenian").replaceAll("Copernicano", "Copernican").replace("Máxima estimada", "Estimated maximum").replace("radio de ", "radius of ");
}

function updateDocument() {
  const language = currentLanguage();
  document.documentElement.lang = language;
  document.querySelectorAll("[data-i18n]").forEach(node => {
    node.textContent = messages[language][node.dataset.i18n] ?? messages.es[node.dataset.i18n] ?? node.textContent;
  });
  document.querySelectorAll("[data-i18n-aria-label]").forEach(node => {
    const key = node.dataset.i18nAriaLabel;
    node.setAttribute("aria-label", messages[language][key] ?? messages.es[key] ?? node.getAttribute("aria-label") ?? "");
  });
  document.querySelectorAll("[data-i18n-title]").forEach(node => {
    const key = node.dataset.i18nTitle;
    node.title = messages[language][key] ?? messages.es[key] ?? node.title;
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach(node => {
    const key = node.dataset.i18nPlaceholder;
    node.setAttribute("placeholder", messages[language][key] ?? messages.es[key] ?? node.getAttribute("placeholder") ?? "");
  });
  document.querySelectorAll("[data-i18n-content]").forEach(node => {
    const key = node.dataset.i18nContent;
    node.setAttribute("content", messages[language][key] ?? messages.es[key] ?? node.getAttribute("content") ?? "");
  });
  const title = document.querySelector("title[data-i18n]");
  if (title) document.title = messages[language][title.dataset.i18n] ?? "GeoTwin Explorer";
  const toggle = document.getElementById("language-toggle");
  if (toggle) {
    toggle.textContent = language === "es" ? "EN" : "ES";
    const label = language === "es" ? messages[language]["language.target.en"] : messages[language]["language.target.es"];
    toggle.setAttribute("aria-label", label);
    toggle.title = label;
    toggle.setAttribute("aria-pressed", String(language === "en"));
  }
}

export function bindLanguageToggle(onChange) {
  updateDocument();
  const toggle = document.getElementById("language-toggle");
  toggle.addEventListener("click", () => {
    document.documentElement.lang = currentLanguage() === "es" ? "en" : "es";
    updateDocument();
    onChange?.(currentLanguage());
  });
}
